#!/usr/bin/env python3
"""Generate the @generated modules of crates/crypto/src/p256_group/. Stdlib only, deterministic.
Run: python3 -I scripts/gen_p256_group.py [--check]
--check regenerates into a temp dir and fails on any byte difference from the committed files.
Not trusted: every emitted datum is re-checked by Verus (certificates by compute_only)."""
import filecmp
import json
import math
import re
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = Path("crates/crypto/src/p256_group")
HEADER = "// @generated by scripts/gen_p256_group.py — do not edit\n"

P = 2**256 - 2**224 + 2**192 + 2**96 - 1
N = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551
B = 0x5AC635D8AA3A93E7B3EBBD55769886BC651D06B0CC53B0F63BCE3C3E27D2604B
SMALL = 1 << 16
# Compute chunk sizes: the interpreter's recursion-depth and step budgets scale with --rlimit, and
# every chunk must pass at --rlimit 0.6 (6x under 4). Exponents are split every W bits, trial
# division every SEG candidates.
W = 48
SEG = 32


# ---------------------------------------------------------------------------------------------
# pratt: Pratt certificates for p and n (data: scripts/p256_pratt.json)
# ---------------------------------------------------------------------------------------------


def trial_prime(r):
    return r >= 2 and all(r % d for d in range(2, int(r**0.5) + 2) if d * d <= r)


def load_pratt():
    raw = json.loads((ROOT / "scripts/p256_pratt.json").read_text())
    cert = {int(q): (a, [(int(r), e) for r, e in fs.items()]) for q, (a, fs) in raw.items()}
    assert P in cert and N in cert
    for q, (a, fs) in cert.items():
        assert q >= SMALL and q > 2 and 1 <= len(fs) <= 12
        prod = 1
        for r, e in fs:
            prod *= r**e
            assert (q - 1) % r == 0 and pow(a, (q - 1) // r, q) != 1
            assert r in cert or (r < SMALL and trial_prime(r)), r
        assert prod == q - 1 and pow(a, q - 1, q) == 1
    return cert


def chunks(e):
    """Exponent prefixes e >> (W * i), shortest first, ending at e itself."""
    c = -(-e.bit_length() // W)
    return [e >> (W * (c - 1 - j)) for j in range(c)]


def gen_powmod_chain(name, A, Q, a, q, ex, e, pre, fact, lit):
    """Lemma `name` ensuring `fact`, i.e. `pre` and a fact about powmod(A, ex, Q), with ex == e.
    One compute assert when e has at most W bits, else a chain of W-bit prefix chunks joined by
    `lemma_powmod_ext`; `pre` is checked in the last chunk."""
    if e.bit_length() <= W:
        return f"""proof fn {name}()
    ensures
        {fact},
{{
    assert({fact}) by (compute_only);
}}

"""
    es = chunks(e)
    ms = [pow(a, x, q) for x in es]
    o, calls = [], []
    for j, (x, m) in enumerate(zip(es, ms)):
        last = j == len(es) - 1
        xs = ex if last else f"{x}nat"
        ms_ = lit(m) or f"{m}int"
        if j == 0:
            st = f"powmod({A}, {xs}, {Q} as int) == {ms_}"
        else:
            st = (f"{pre if last else ''}shr({xs}, {W}) == {es[j - 1]}nat && "
                  f"powmod_ext({ms[j - 1]}int, {A}, {xs}, {W}, {Q} as int) == {ms_}")
            calls.append(f"    lemma_powmod_ext({A}, {xs}, {W}, {Q} as int);\n")
        o.append(f"""proof fn {name}_c{j}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
        calls.insert(len(calls) - (1 if j else 0), f"    {name}_c{j}();\n")
    o.append(f"""proof fn {name}()
    ensures
        {fact},
{{
{"".join(calls)}}}

""")
    return "".join(o)


def gen_trial(r):
    """Primality of r < 2^16 by trial division, in SEG-candidate chunks joined by `lemma_trial_seg`."""
    d = math.isqrt(r) + 1
    if d - 2 <= SEG:
        return f"""proof fn lemma_trial_{r}()
    ensures
        crate::rsa::is_prime({r}),
{{
    assert(trial_ok({r})) by (compute_only);
    lemma_trial_prime({r});
}}

"""
    bounds = list(range(2, d, SEG)) + [d]
    o, calls = [], []
    for i in reversed(range(len(bounds) - 1)):
        lo, hi = bounds[i], bounds[i + 1]
        st = f"trial_seg({r}, {lo}, {hi})" + (f" && trial_from({r}, {d})" if hi == d else "")
        o.insert(0, f"""proof fn lemma_trial_{r}_c{i}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
        calls.append(f"    lemma_trial_{r}_c{i}();\n    lemma_trial_seg({r}, {lo}, {hi});\n")
    o.append(f"""proof fn lemma_trial_{r}()
    ensures
        crate::rsa::is_prime({r}),
{{
{"".join(calls)}    lemma_trial_prime({r});
}}

""")
    return "".join(o)


def gen_pratt():
    cert = load_pratt()
    order = sorted(cert)  # children are smaller than parents, so ascending is leaves-first
    inner = [q for q in order if q not in (P, N)]
    label = {q: str(i) for i, q in enumerate(inner)}
    label[P], label[N] = "P", "N"
    small = sorted({r for _, fs in cert.values() for r, _ in fs if r not in cert})
    o = [HEADER]
    o.append("""//! Pratt certificates for P-256's p and n: each node q has a witness A and the factorization FS
//! of q - 1, checked by `compute_only` one modular power per lemma and assembled into
//! `lucas_ok`; prime factors below 2^16 are checked by trial division.
// Lucas 1876 / Pratt 1975
#![allow(non_snake_case)]
#[allow(unused_imports)]
use super::nt::*;
use vstd::prelude::*;
#[allow(unused_imports)]
use vstd::arithmetic::power::*;

verus! {

""")
    for r in small:
        o.append(gen_trial(r))
    for q in order:
        a, fs = cert[q]
        x = label[q]
        Q, A, FS = f"Q_{x}()", f"A_{x}()", f"FS_{x}()"
        seq = ", ".join(f"({r}nat, {e}nat)" for r, e in fs)
        shape = " && ".join(
            [f"{Q} > 2", f"{FS}.len() == {len(fs)}", f"prod_pow({FS}) == {Q} - 1"]
            + [f"{FS}[{k}].0 == {r}nat" for k, (r, _) in enumerate(fs)]
        )
        full = f"powmod({A}, ({Q} - 1) as nat, {Q} as int) == 1"
        o.append(f"""// ---- node {x}: q = {q}

pub(crate) open spec fn Q_{x}() -> nat {{
    {q}nat
}}

pub(crate) open spec fn A_{x}() -> int {{
    {a}int
}}

pub(crate) open spec fn FS_{x}() -> Seq<(nat, nat)> {{
    seq![{seq}]
}}

proof fn lemma_cert_{x}_shape()
    ensures
        {shape},
{{
    assert({shape}) by (compute_only);
}}

""")
        o.append(gen_powmod_chain(f"lemma_cert_{x}_full", A, Q, a, q, f"({Q} - 1) as nat", q - 1, "",
                                  full, lambda m: "1" if m == 1 else None))
        for k, (r, _) in enumerate(fs):
            rk = f"({FS}[{k}].0 as int)"
            pre = f"{FS}[{k}].0 > 1 && ({Q} - 1) % {rk} == 0"
            fact = f"{pre} && powmod({A}, (({Q} - 1) / {rk}) as nat, {Q} as int) != 1"
            o.append(gen_powmod_chain(f"lemma_cert_{x}_{k}", A, Q, a, q, f"(({Q} - 1) / {rk}) as nat",
                                      (q - 1) // r, pre + " && ", fact, lambda m: None))
        calls = "".join(f"    lemma_cert_{x}_{k}();\n" for k in range(len(fs)))
        o.append(f"""proof fn lemma_cert_{x}()
    ensures
        lucas_ok({Q}, {A}, {FS}),
{{
    lemma_cert_{x}_shape();
    lemma_cert_{x}_full();
{calls}    reveal_with_fuel(lucas_fs_ok, {len(fs) + 1});
}}

""")
        cases = " else ".join(
            f"if i == {k} {{\n            "
            + (f"lemma_prime_{label[r]}();" if r in cert else f"lemma_trial_{r}();")
            + "\n        }"
            for k, (r, _) in enumerate(fs)
        )
        root = q in (P, N)
        flt = (f"""
        forall|x: int|
            x % ({Q} as int) != 0 ==> #[trigger] (pow(x, ({Q} - 1) as nat) % ({Q} as int)) == 1,"""
               if root else "")
        o.append(f"""{"pub(crate) " if root else ""}proof fn lemma_prime_{x}()
    ensures
        crate::rsa::is_prime({Q}),{flt}
{{
    lemma_cert_{x}();
    lemma_cert_{x}_shape();
    assert forall|i: int| 0 <= i < {FS}.len() implies crate::rsa::is_prime(#[trigger] {FS}[i].0) by {{
        {cases}
    }}
    lemma_lucas({Q}, {A}, {FS});
}}

""")
    for x, f in (("p", "p256_p"), ("n", "p256_n")):
        X = x.upper()
        o.append(f"""pub(crate) proof fn lemma_{x}_prime()
    ensures
        crate::rsa::is_prime(crate::p256::{f}() as nat),
{{
    lemma_prime_{X}();
    super::field::lemma_group_consts();
}}

""")
    o[-1] = o[-1].rstrip("\n") + "\n\n} // verus!\n"
    return "".join(o)


# ---------------------------------------------------------------------------------------------
# torsion: g = x^p mod f and a Bezout certificate u f + v (g - x) == 1, f = x^3 - 3x + b
# ---------------------------------------------------------------------------------------------


def qmul(a, b):
    """Mirror of torsion.rs `qmul` (x^3 == 3x - b, x^4 == 3x^2 - b x, mod P)."""
    d0 = a[0] * b[0]
    d1 = a[0] * b[1] + a[1] * b[0]
    d2 = a[0] * b[2] + a[1] * b[1] + a[2] * b[0]
    d3 = (a[1] * b[2] + a[2] * b[1]) % P
    d4 = a[2] * b[2] % P
    return ((d0 - B * d3) % P, (d1 + 3 * d3 - B * d4) % P, (d2 + 3 * d4) % P)


def qpow(a, e):
    """Mirror of torsion.rs `qpow`."""
    if e == 0:
        return (1, 0, 0)
    s = qpow(a, e // 2)
    s = qmul(s, s)
    return qmul(s, a) if e % 2 else s


def ptrim(a):
    a = [c % P for c in a]
    while a and a[-1] == 0:
        a.pop()
    return a


def psub(a, b):
    n = max(len(a), len(b))
    return ptrim([(a[i] if i < len(a) else 0) - (b[i] if i < len(b) else 0) for i in range(n)])


def pmul(a, b):
    r = [0] * max(0, len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            r[i + j] += x * y
    return ptrim(r)


def pdivmod(a, b):
    a, q, inv = a[:], [0] * max(1, len(a) - len(b) + 1), pow(b[-1], -1, P)
    while len(a) >= len(b):
        c, k = a[-1] * inv % P, len(a) - len(b)
        q[k] = c
        a = ptrim([x - (c * b[i - k] if 0 <= i - k < len(b) else 0) for i, x in enumerate(a)])
    return ptrim(q), a


def xp_chain(q2):
    """lemma_xp_mod_f: qpow(X, p) == XP_POLY in W-bit prefix chunks joined by `lemma_qpow_ext`."""
    q2p = lambda a: f"({q2(a)})"  # struct literals need parentheses in expressions
    es = chunks(P)
    ms = [qpow((0, 1, 0), x) for x in es]
    o, calls = [], []
    for j, (x, m) in enumerate(zip(es, ms)):
        last = j == len(es) - 1
        xs, mv = ("P_LIT() as nat", "XP_POLY()") if last else (f"{x}nat", q2p(m))
        if j == 0:
            st = f"qpow(X(), {xs}) == {mv}"
        else:
            st = f"shr({xs}, {W}) == {es[j - 1]}nat && qpow_ext({q2p(ms[j - 1])}, X(), {xs}, {W}) == {mv}"
        o.append(f"""proof fn lemma_xp_c{j}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
        calls.append(f"    lemma_xp_c{j}();\n" + (f"    lemma_qpow_ext(X(), {xs}, {W});\n" if j else ""))
    return "".join(o) + f"""pub(crate) proof fn lemma_xp_mod_f()
    ensures
        qpow(X(), P_LIT() as nat) == XP_POLY(),
{{
{"".join(calls)}}}
"""


def gen_torsion():
    g = qpow((0, 1, 0), P)
    f = ptrim([B, -3, 0, 1])
    h = ptrim([g[0], g[1] - 1, g[2]])
    # extended Euclid on (f, h)
    r0, r1, s0, s1, t0, t1 = f, h, [1], [], [], [1]
    while r1:
        q, r = pdivmod(r0, r1)
        r0, r1, s0, s1, t0, t1 = r1, r, s1, psub(s0, pmul(q, s1)), t1, psub(t0, pmul(q, t1))
    assert len(r0) == 1, "gcd(f, x^p - x) is not constant: f has a root mod p"
    c = pow(r0[0], -1, P)
    u, v = ptrim([x * c for x in s0]), ptrim([x * c for x in t0])
    assert len(u) <= 2 and len(v) <= 3
    assert psub(pmul(u, f), psub([1], pmul(v, h))) == []
    u, v = (u + [0, 0])[:2], (v + [0, 0, 0])[:3]
    assert qmul(tuple(v), tuple((h + [0, 0, 0])[:3])) == (1, 0, 0)  # v == 1 / (g - x) mod f
    q2 = lambda a: f"Q2 {{ c0: {a[0]}int, c1: {a[1]}int, c2: {a[2]}int }}"
    return HEADER + f"""//! The torsion certificate: g = x^p mod (f, p) and Bezout polynomials u, v with
//! u f + v (g - x) == 1 mod p, f = x^3 - 3x + b, both checked by `compute_only`.
#![allow(non_snake_case)]
#[allow(unused_imports)]
use super::field::*;
#[allow(unused_imports)]
use super::nt::*;
#[allow(unused_imports)]
use super::torsion::*;
use vstd::prelude::*;

verus! {{

/// x^p mod (f, p).
pub(crate) open spec fn XP_POLY() -> Q2 {{
    {q2(g)}
}}

pub(crate) open spec fn U() -> (int, int) {{
    ({u[0]}int, {u[1]}int)
}}

pub(crate) open spec fn V() -> Q2 {{
    {q2(v)}
}}

{xp_chain(q2)}
pub(crate) proof fn lemma_bezout_cert()
    ensures
        bez_ok(U(), V(), XP_POLY()),
{{
    assert(bez_ok(U(), V(), XP_POLY())) by (compute_only);
}}

}} // verus!
"""


# ---------------------------------------------------------------------------------------------
# grid_small: curve-point grids, and the chunks of the RCB correspondence identities (rcb.rs)
# ---------------------------------------------------------------------------------------------

GRID_N = 13
GRID_X = [0, 5, 6, 8, 9, 12, 13, 17, 23, 24, 25, 26, 29]  # planner check (plan Task 6)
SENT = [-1, -1, -1]


def fcurve(x):
    return (x**3 - 3 * x + B) % P


def grid_points():
    """The first GRID_N x >= 0 with f(x) a nonzero square mod p, and y = f(x)^((p+1)/4)."""
    assert P % 4 == 3
    xs, x = [], 0
    while len(xs) < GRID_N:
        if fcurve(x) and pow(fcurve(x), (P - 1) // 2, P) == 1:
            xs.append(x)
        x += 1
    ys = [pow(fcurve(x), (P + 1) // 4, P) for x in xs]
    assert xs == GRID_X and all(y * y % P == fcurve(x) and y for x, y in zip(xs, ys))
    return xs, ys


def rmax(u, v):
    """Mirror of red.rs `rmax`."""
    if u[0] < 0:
        return v
    if v[0] < 0:
        return u
    return [max(a, b) for a, b in zip(u, v)]


class Deg:
    """Mirror of red.rs `rd_*` (8 x 3 degree tables, sentinel row[0] < 0)."""

    def k(self, c):
        return [[0, 0, 0]] + [SENT] * 7

    def x(self, i):
        return [[int(i == j) for j in range(3)]] + [SENT] * 7

    def y(self, i):
        return [[0, 0, 0] if s == 1 << i else SENT for s in range(8)]

    def add(self, a, b):
        return [rmax(a[s], b[s]) for s in range(8)]

    @staticmethod
    def pair(a, b, s, r):
        u, v, m = a[s], b[s ^ r], s & (s ^ r)
        if u[0] < 0 or v[0] < 0:
            return SENT
        return [u[i] + v[i] + 3 * (m >> i & 1) for i in range(3)]

    def mul(self, a, b):
        out = []
        for r in range(8):
            acc = self.pair(a, b, 0, r)
            for k in range(1, 8):
                acc = rmax(acc, self.pair(a, b, k, r))
            out.append(acc)
        return out

    def sc(self, c, a):
        return self.mul(self.k(c), a)

    def sub(self, a, b):
        return self.add(a, self.mul(self.k(-1), b))


class MDeg(Deg):
    """Mirror of poly.rs `dsum`/`dmax` for the y-free identities (rcb.rs `*_ds`)."""

    def k(self, c):
        return [0, 0, 0]

    def x(self, i):
        return [int(i == j) for j in range(3)]

    def add(self, a, b):
        return [max(u, v) for u, v in zip(a, b)]

    def mul(self, a, b):
        return [u + v for u, v in zip(a, b)]


class Plain:
    """Mirror of rcb.rs's plain spec fns (`fm` reduces each product mod p)."""

    def __init__(self, xs, ys):
        self.xs, self.ys = xs, ys

    def k(self, c):
        return c

    def x(self, i):
        return self.xs[i]

    def y(self, i):
        return self.ys[i]

    def add(self, a, b):
        return a + b

    def sub(self, a, b):
        return a - b

    def mul(self, a, b):
        return a * b % P

    def sc(self, c, a):
        return c * a


def rcb(R, a, b):
    """Mirror of rcb.rs `rcb`/`rcb_d` (RCB 2016 eq. (1), a = -3)."""
    x1, y1, z1 = a
    x2, y2, z2 = b
    b3 = R.k(3 * B)
    t0 = R.add(R.mul(x1, z2), R.mul(x2, z1))
    y12, z12 = R.mul(y1, y2), R.mul(z1, z2)
    bz = R.mul(b3, z12)
    u = R.sub(R.add(y12, R.sc(3, t0)), bz)
    v = R.add(R.sub(y12, R.sc(3, t0)), bz)
    w = R.sub(R.add(R.sc(-3, R.mul(x1, x2)), R.mul(b3, t0)), R.sc(9, z12))
    s = R.add(R.mul(x1, y2), R.mul(x2, y1))
    r = R.add(R.mul(y1, z2), R.mul(y2, z1))
    q = R.sub(R.sc(3, R.mul(x1, x2)), R.sc(3, z12))
    return (R.sub(R.mul(s, u), R.mul(r, w)), R.add(R.mul(v, u), R.mul(q, w)),
            R.add(R.mul(r, v), R.mul(s, q)))


def g_chord(R):
    x0, x1, y0, y1 = R.x(0), R.x(1), R.y(0), R.y(1)
    d, ln = R.sub(x1, x0), R.sub(y1, y0)
    d2 = R.mul(d, d)
    d3 = R.mul(d2, d)
    xn = R.sub(R.mul(ln, ln), R.mul(R.add(x0, x1), d2))
    yn = R.sub(R.mul(ln, R.sub(R.mul(x0, d2), xn)), R.mul(y0, d3))
    return d2, d3, xn, yn


def g_dbl(R):
    x0, y0 = R.x(0), R.y(0)
    e, ln = R.sc(2, y0), R.sub(R.sc(3, R.mul(x0, x0)), R.k(3))
    e2 = R.mul(e, e)
    e3 = R.mul(e2, e)
    xn = R.sub(R.mul(ln, ln), R.mul(R.sc(2, x0), e2))
    yn = R.sub(R.mul(ln, R.sub(R.mul(x0, e2), xn)), R.mul(y0, e3))
    return e2, e3, xn, yn


def g_fv(R, x):
    return R.add(R.sub(R.mul(R.mul(x, x), x), R.sc(3, x)), R.k(B))


def g_w(R, x1, x2):
    s, t = R.add(x1, x2), R.mul(x1, x2)
    ss, b = R.mul(s, s), R.k(B)
    bc = R.add(R.add(R.mul(ss, s), R.sc(6, R.mul(s, t))), R.sc(6, s))
    c0 = R.sub(R.sub(R.sub(R.sub(R.mul(R.mul(t, t), t), R.sc(3, R.mul(t, ss))), R.sc(3, R.mul(t, t))),
                     R.sc(9, ss)), R.sc(9, t))
    return R.add(R.add(R.sub(R.mul(b, bc), R.sc(8, R.mul(b, b))), c0), R.k(27))


def g_clo(R, xn, yn, d):
    return R.sub(R.mul(yn, yn), R.add(R.sub(R.mul(R.mul(xn, xn), xn), R.sc(3, R.mul(xn, R.mul(d, d)))),
                                      R.mul(R.k(B), R.mul(d, R.mul(d, d)))))


def g_pts(R):
    return (R.x(0), R.y(0), R.k(1)), (R.x(1), R.y(1), R.k(1))


def g_inv(R):
    p, _ = g_pts(R)
    return rcb(R, p, (p[0], R.sub(R.k(P), p[1]), p[2]))


def i_chord_z(R):
    p, q = g_pts(R)
    d2, d3, xn, yn = g_chord(R)
    zm = rcb(R, p, (q[0], R.sc(-1, q[1]), q[2]))[2]
    return R.sub(R.mul(rcb(R, p, q)[2], zm), R.mul(d3, g_w(R, R.x(0), R.x(1))))


def i_coord(pp, ch, k, dk):
    """X3 d^2 - xn Z3 (k = 0, dk = 0) or Y3 d^3 - yn Z3 (k = 1, dk = 1)."""
    def f(R):
        p, q = g_pts(R)
        o, c = rcb(R, p, q if pp else p), ch(R)
        return R.sub(R.mul(o[k], c[dk]), R.mul(c[2 + k], o[2]))
    return f


# rcb.rs's identities, in its order: name -> mirror
IDS = {
    "chord_x": i_coord(True, g_chord, 0, 0),
    "chord_y": i_coord(True, g_chord, 1, 1),
    "chord_z": i_chord_z,
    "dbl_x": i_coord(False, g_dbl, 0, 0),
    "dbl_y": i_coord(False, g_dbl, 1, 1),
    "dbl_z": lambda R: R.sub(rcb(R, *[g_pts(R)[0]] * 2)[2], R.mul(R.sc(8, R.y(0)), g_fv(R, R.x(0)))),
    "inv_x": lambda R: g_inv(R)[0],
    "inv_z": lambda R: g_inv(R)[2],
    "inv_y": lambda R: R.sub(g_inv(R)[1], rcb(R, *[g_pts(R)[0]] * 2)[1]),
    "closure_chord": lambda R: g_clo(R, *(lambda c: (c[2], c[3], c[0]))(g_chord(R))),
    "closure_dbl": lambda R: g_clo(R, *(lambda c: (c[2], c[3], c[0]))(g_dbl(R))),
}


def g_r1(R, x1, x2):
    s, t = R.add(x1, x2), R.mul(x1, x2)
    return R.sc(2, R.sub(R.add(R.mul(s, s), R.sc(2, t)), R.k(6)))


def g_r0(R, x1, x2):
    s, t = R.add(x1, x2), R.mul(x1, x2)
    return R.sc(-2, R.add(R.add(R.k(-4 * B), R.mul(t, s)), R.sc(3, s)))


def g_q(R, x1, x2, e):
    s, t = R.add(x1, x2), R.mul(x1, x2)
    return R.sub(R.add(R.sc(2, R.mul(e, e)), R.mul(s, e)), R.add(t, R.k(3)))


def i_res1(R):
    x1, x2 = R.x(0), R.x(1)
    s, t = R.add(x1, x2), R.mul(x1, x2)
    a, b = g_r0(R, x1, x2), g_r1(R, x1, x2)
    return R.add(R.sub(R.sub(R.sc(2, R.mul(a, a)), R.mul(R.mul(s, a), b)), R.mul(R.add(t, R.k(3)), R.mul(b, b))),
                 R.sc(16, g_w(R, x1, x2)))


def i_res2(R):
    x1, x2, e = R.x(0), R.x(1), R.x(2)
    lin = R.sub(R.sc(4, e), R.sc(2, R.add(x1, x2)))
    return R.sub(R.sub(R.sub(R.sc(8, g_fv(R, e)), R.mul(g_q(R, x1, x2, e), lin)), R.mul(g_r1(R, x1, x2), e)),
                 g_r0(R, x1, x2))


RES = {"res1": i_res1, "res2": i_res2}


def rd_sizes(d):
    rows = [r for r in d if r[0] >= 0]
    return [max(r[i] for r in rows) + 1 for i in range(3)]


def sgn(sig, ys):
    return [-y if sig >> i & 1 else y for i, y in enumerate(ys)]


def point_add(a, b):
    """Literal transcription of p256.rs `point_add` (None is Infinity)."""
    if a is None:
        return b
    if b is None:
        return a
    (x1, y1), (x2, y2) = a, b
    if x1 == x2 and (y1 + y2) % P == 0:
        return None
    finv = lambda x: pow(x, P - 2, P)
    lam = (3 * x1 * x1 - 3) * finv(2 * y1) % P if x1 == x2 else (y2 - y1) * finv(x2 - x1) % P
    x3 = (lam * lam - x1 - x2) % P
    return (x3, (lam * (x1 - x3) - y1) % P)


def rcb_check():
    """RCB-decoded vs point_add: 200 random pairs of multiples of G, plus G+G, G+(-G), G+O."""
    src = (ROOT / OUT / "field.rs").read_text()
    G = tuple(int(re.search(rf"fn {c}_LIT\(\) -> int {{\s*(\d+)int", src).group(1)) for c in ("GX", "GY"))
    assert fcurve(G[0]) == G[1] ** 2 % P

    def mult(k):
        acc, base = None, G
        while k:
            if k & 1:
                acc = point_add(acc, base)
            base, k = point_add(base, base), k >> 1
        return acc

    enc = lambda a: (0, 1, 0) if a is None else (a[0], a[1], 1)
    dec = lambda c: None if c[2] % P == 0 else (c[0] * pow(c[2], P - 2, P) % P, c[1] * pow(c[2], P - 2, P) % P)
    rng = __import__("random").Random(20261028)
    pairs = [(mult(rng.randrange(1, N)), mult(rng.randrange(1, N))) for _ in range(200)]
    pairs += [(G, G), (G, (G[0], P - G[1])), (G, None)]
    ok = sum(dec(rcb(Plain([], []), enc(a), enc(b))) == point_add(a, b) for a, b in pairs)
    assert ok == len(pairs) == 203
    print(f"rcb vs point_add: {ok}/{len(pairs)}")


def grid_sizes():
    """Identity name -> grid sizes [n0, n1, n2] (tracked degree + 1)."""
    sz = {n: rd_sizes(f(Deg())) for n, f in IDS.items()}
    sz.update({n: [d + 1 for d in f(MDeg())] for n, f in RES.items()})
    assert all(1 <= v <= GRID_N for n in sz.values() for v in n) and all(sz[n][2] == 1 for n in IDS)
    return sz


def grid_check(gx, gy, sz):
    ok = 0
    for n, f in IDS.items():
        n0, n1, _ = sz[n]
        ok += all(f(Plain([gx[i], gx[j], gx[0]], sgn(sig, [gy[i], gy[j], gy[0]]))) % P == 0
                  for i in range(n0) for j in range(n1) for sig in range(8))
    for n, f in RES.items():
        n0, n1, n2 = sz[n]
        ok += all(f(Plain([i, j, l], [])) % P == 0 for i in range(n0) for j in range(n1) for l in range(n2))
    assert ok == len(IDS) + len(RES)
    print(f"all identities zero on grid: {ok}/{len(IDS) + len(RES)}")


# Identities with two RCB degree tables exceed one compute assert's budget at --rlimit 0.6: the
# tables are emitted as literals, each checked by its own compute assert, and `idd_<name>_of`
# takes them in place of the RCB calls.
SPLIT = {
    "chord_z": [("rcb_d(pt_d(0), pt_d(1))", lambda R: rcb(R, *g_pts(R))),
                ("rcb_d(pt_d(0), ptm_d())", lambda R: rcb(R, g_pts(R)[0], (R.x(1), R.sc(-1, R.y(1)), R.k(1))))],
    "inv_y": [("rcb_d(pt_d(0), ptn_d())", lambda R: g_inv(R)), ("rcb_d(pt_d(0), pt_d(0))", lambda R: rcb(R, *[g_pts(R)[0]] * 2))],
}


def pd_lit(t):
    rd = lambda d: "seq![" + ", ".join("seq![" + ", ".join(f"{v}int" if k == 0 else str(v) for k, v in enumerate(r))
                                       + "]" for r in d) + "]"
    return f"PD {{\n        x: {rd(t[0])},\n        y: {rd(t[1])},\n        z: {rd(t[2])},\n    }}"


def deg_lemma(name, n):
    ns = f"seq![{n[0]}int, {n[1]}, {n[2]}]"
    if name not in SPLIT:
        return f"""pub(crate) proof fn lemma_deg_{name}()
    ensures
        deg_ok(idd_{name}(), {ns}),
{{
    assert(deg_ok(idd_{name}(), {ns})) by (compute_only);
}}

"""
    o, calls = [], []
    for k, (expr, mirror) in enumerate(SPLIT[name]):
        st = f"{expr} == pdl_{name}_{k}()"
        o.append(f"""/// {expr}.
pub(crate) open spec fn pdl_{name}_{k}() -> PD {{
    {pd_lit(mirror(Deg()))}
}}

proof fn lemma_deg_{name}_t{k}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
        calls.append(f"    lemma_deg_{name}_t{k}();\n")
    lits = ", ".join(f"pdl_{name}_{k}()" for k in range(len(SPLIT[name])))
    full = f"deg_ok(idd_{name}_of({lits}), {ns})"
    return "".join(o) + f"""proof fn lemma_deg_{name}_c()
    ensures
        {full},
{{
    assert({full}) by (compute_only);
}}

pub(crate) proof fn lemma_deg_{name}()
    ensures
        deg_ok(idd_{name}(), {ns}),
{{
{"".join(calls)}    lemma_deg_{name}_c();
}}

"""


def int_chain(name, vals):
    body = " else ".join(f"if i == {k} {{\n        {v}int\n    }}" for k, v in enumerate(vals))
    return f"pub(crate) open spec fn {name}(i: int) -> int {{\n    {body} else {{\n        0\n    }}\n}}\n\n"


def conj(terms, ind="    "):
    return f"\n{ind}    && ".join(terms)


def gen_grid_small():
    gx, gy = grid_points()
    sz = grid_sizes()
    grid_check(gx, gy, sz)
    rcb_check()
    n = GRID_N
    o = [HEADER, f"""//! Grid data and chunked `compute_only` checks for rcb.rs's identities: the first {n} x >= 0 with
//! f(x) = x^3 - 3x + b a nonzero square mod p and y = f(x)^((p+1)/4), each identity at every grid
//! cell and y-sign choice, and each identity's degree table against its grid sizes.
#[allow(unused_imports)]
use super::field::*;
#[allow(unused_imports)]
use super::rcb::*;
#[allow(unused_imports)]
use super::red::*;
#[allow(unused_imports)]
use crate::p256::*;
use vstd::prelude::*;

verus! {{

"""]
    o.append(int_chain("gx", gx))
    o.append(int_chain("gy", gy))
    lit = ([f"pt_lit(gx({t}), gy({t}))" for t in range(n)] + ["0 <= gx(0)"]
           + [f"gx({t}) < gx({t + 1})" for t in range(n - 1)] + [f"gx({n - 1}) < P_LIT()"])
    split = " else ".join(f"if t == {t} {{\n            }}" for t in range(n))
    o.append(f"""/// The grid points are curve points with y != 0, and the x-values increase within [0, p).
pub(crate) open spec fn pts_lit() -> bool {{
    {conj(lit)}
}}

proof fn lemma_grid_pts_lit()
    ensures
        pts_lit(),
{{
    assert(pts_lit()) by (compute_only);
}}

proof fn lemma_gx_lt(i: int, j: int)
    requires
        pts_lit(),
        0 <= i < j < {n},
    ensures
        gx(i) < gx(j),
    decreases j - i,
{{
    if i + 1 < j {{
        lemma_gx_lt(i + 1, j);
    }}
    assert(gx(i) < gx(i + 1)) by {{
        {split.replace("t ==", "i ==").replace("            ", "        ")}
    }}
}}

/// `lemma_identity`'s grid-point premises at the {n} points.
pub(crate) proof fn lemma_grid_pts_ok()
    ensures
        forall|t: int| 0 <= t < {n} ==> #[trigger] gpt_ok(gx(t), gy(t)),
        forall|i: int, j: int|
            0 <= i < {n} && 0 <= j < {n} && i != j ==> fmod(#[trigger] gx(i)) != fmod(#[trigger] gx(j)),
{{
    lemma_grid_pts_lit();
    lemma_group_consts();
    reveal(pt_lit);
    assert forall|t: int| 0 <= t < {n} implies #[trigger] gpt_ok(gx(t), gy(t)) && 0 <= gx(t) < P_LIT() by {{
        assert(pt_lit(gx(t), gy(t)) && 0 <= gx(t) < P_LIT()) by {{
            {split}
        }}
    }}
    assert forall|i: int, j: int| 0 <= i < {n} && 0 <= j < {n} && i != j implies fmod(#[trigger] gx(i))
        != fmod(#[trigger] gx(j)) by {{
        if i < j {{
            lemma_gx_lt(i, j);
        }} else {{
            lemma_gx_lt(j, i);
        }}
        assert(gpt_ok(gx(i), gy(i)) && gpt_ok(gx(j), gy(j)));
        vstd::arithmetic::div_mod::lemma_small_mod(gx(i) as nat, P_LIT() as nat);
        vstd::arithmetic::div_mod::lemma_small_mod(gx(j) as nat, P_LIT() as nat);
    }}
}}

/// The grid sequences `lemma_identity` takes hold the index fns the chunks evaluate.
pub(crate) proof fn lemma_grid_seq(n0: int, n1: int, n2: int, i: int, j: int, l: int)
    requires
        0 <= i < n0 && 0 <= j < n1 && 0 <= l < n2,
    ensures
        gpt(grid_x(n0, n1, n2), i, j, l) == seq![gx(i), gx(j), gx(l)],
        gpt(grid_y(n0, n1, n2), i, j, l) == seq![gy(i), gy(j), gy(l)],
{{
    assert(gpt(grid_x(n0, n1, n2), i, j, l) =~= seq![gx(i), gx(j), gx(l)]);
    assert(gpt(grid_y(n0, n1, n2), i, j, l) =~= seq![gy(i), gy(j), gy(l)]);
}}

""")
    for name in IDS:
        n0, n1, n2 = sz[name]
        cell = "".join(f"\n    &&& id_{name}(xs, sgn({k}, ys)) % P_LIT() == 0" for k in range(8))
        two = n1 > 1
        perm = "|i: int, l: int, j: int|" if two else "|j: int, l: int, i: int|"
        o.append(f"// ---- {name}: grid {n0} x {n1} x {n2}\n\n")
        o.append(deg_lemma(name, (n0, n1, n2)))
        o.append(f"""

#[verifier::opaque]
pub(crate) open spec fn cell_{name}(i: int, j: int, l: int) -> bool {{
    let xs = seq![gx(i), gx(j), gx(l)];
    let ys = seq![gy(i), gy(j), gy(l)];{cell}
}}

pub(crate) open spec fn c_{name}() -> spec_fn(int, int, int) -> bool {{
    {perm} cell_{name}(i, j, l)
}}

""")
        rows = range(n0) if two else [0]
        hi = n1 if two else n0
        calls = []
        for i in rows:
            st = f"cells_ok(c_{name}(), {i}, 0, 0, {hi})"
            # the row's cells as a forall (Z3, kept small: one row per lemma)
            q, cl, ap = (("j", f"cell_{name}({i}, j, 0)", f"c_{name}()({i}, 0, j)") if two
                         else ("i", f"cell_{name}(i, 0, 0)", f"c_{name}()(0, 0, i)"))
            o.append(f"""proof fn lemma_{name}_r{i}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

proof fn lemma_{name}_w{i}()
    ensures
        forall|{q}: int| 0 <= {q} < {hi} ==> #[trigger] {cl},
{{
    lemma_{name}_r{i}();
    lemma_cells_forall(c_{name}(), {i}, 0, 0, {hi});
    assert forall|{q}: int| 0 <= {q} < {hi} implies #[trigger] {cl} by {{
        assert({ap});
    }}
}}

""")
            calls.append(f"    lemma_{name}_w{i}();\n")
        if two:
            pick = " else ".join(f"if i == {i} {{\n            }}" for i in rows)
            inst = f"""        assert(cell_{name}(i, j, l)) by {{
            {pick}
        }}
"""
        else:
            inst = f"        assert(cell_{name}(i, j, l));\n"
        o.append(f"""pub(crate) proof fn lemma_cells_{name}()
    ensures
        forall|i: int, j: int, l: int|
            0 <= i < {n0} && 0 <= j < {n1} && 0 <= l < {n2} ==> #[trigger] sg_cell(fn_{name}(), i, j, l),
{{
    hide(id_{name});
{"".join(calls)}    assert forall|i: int, j: int, l: int| 0 <= i < {n0} && 0 <= j < {n1} && 0 <= l < {n2} implies #[trigger] sg_cell(
        fn_{name}(),
        i,
        j,
        l,
    ) by {{
{inst}        reveal(cell_{name});
        reveal(sg_cell);
    }}
}}

""")
    # y-free identities: grid {{0, ..., n - 1}} per variable
    for name, args in (("res1", "i, j"), ("res2", "i, j, l")):
        n0, n1, n2 = sz[name]
        three = name == "res2"
        perm = "|i: int, j: int, l: int|" if three else "|i: int, l: int, j: int|"
        rows = [(i, j) for i in range(n0) for j in range(n1)] if three else [(i, 0) for i in range(n0)]
        hi = n2 if three else n1
        st = conj([f"cells_ok(c_{name}(), {i}, {j}, 0, {hi})" for i, j in rows], "    ")
        calls = "".join(f"    lemma_cells_forall(c_{name}(), {i}, {j}, 0, {hi});\n" for i, j in rows)
        if three:
            pick = " else ".join(f"if i == {i} && j == {j} {{\n            }}" for i, j in rows)
            inst = f"c_{name}()(i, j, l)"
            qv, rng = "i: int, j: int, l: int", f"0 <= i < {n0} && 0 <= j < {n1} && 0 <= l < {n2}"
        else:
            pick = " else ".join(f"if i == {i} {{\n            }}" for i, _ in rows)
            inst = f"c_{name}()(i, 0, j)"
            qv, rng = "i: int, j: int", f"0 <= i < {n0} && 0 <= j < {n1}"
        o.append(f"""// ---- {name}: grid {n0} x {n1} x {n2} over {{0, 1, ...}}

#[verifier::opaque]
pub(crate) open spec fn cell_{name}(i: int, j: int, l: int) -> bool {{
    id_{name}({args}) % P_LIT() == 0
}}

pub(crate) open spec fn c_{name}() -> spec_fn(int, int, int) -> bool {{
    {perm} cell_{name}(i, j, l)
}}

pub(crate) proof fn lemma_deg_{name}()
    ensures
        ds_ok({name}_ds(), seq![{n0}int, {n1}, {n2}]),
{{
    assert(ds_ok({name}_ds(), seq![{n0}int, {n1}, {n2}])) by (compute_only);
}}

proof fn lemma_{name}_c()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

pub(crate) proof fn lemma_cells_{name}()
    ensures
        forall|{qv}| #![trigger id_{name}({args})] {rng} ==> id_{name}({args}) % P_LIT() == 0,
{{
    hide(id_{name});
    lemma_{name}_c();
{calls}    assert forall|{qv}| #![trigger id_{name}({args})] {rng} implies id_{name}({args}) % P_LIT() == 0 by {{
        assert({inst}) by {{
            {pick}
        }}
        reveal(cell_{name});
    }}
}}

""")
    o[-1] = o[-1].rstrip("\n") + "\n\n} // verus!\n"
    return "".join(o)


# ---------------------------------------------------------------------------------------------
# grid_assoc_{a,b,c,d}: the associativity minors (assoc_id.rs) on the 10 x 13 x 10 grid
# ---------------------------------------------------------------------------------------------

ASSOC_N = [10, 13, 10]
ASSOC_I = {"a": range(0, 3), "b": range(3, 6), "c": range(6, 8), "d": range(8, 10)}
ASSOC_H = 5  # grid cells (x 8 y-signs) per compute chunk; passes at --rlimit 0.15


def a_pts(R):
    return [(R.x(i), R.y(i), R.k(1)) for i in range(3)]


def a_minor(R, m, l, r):
    """Mirror of assoc_id.rs `minor`/`minor_d`."""
    u, v = [(0, 1), (0, 2), (1, 2)][m]
    return R.sub(R.mul(l[u], r[v]), R.mul(r[u], l[v]))


# The four RCB degree tables, outermost last: (Verus expression, mirror).
ASSOC_LV = {
    "01": ("rcb_d(pt_d(0), pt_d(1))", lambda R, t: rcb(R, *a_pts(R)[:2])),
    "12": ("rcb_d(pt_d(1), pt_d(2))", lambda R, t: rcb(R, *a_pts(R)[1:])),
    "l": ("rcb_d(pdl_assoc_01(), pt_d(2))", lambda R, t: rcb(R, t["01"], a_pts(R)[2])),
    "r": ("rcb_d(pt_d(0), pdl_assoc_12())", lambda R, t: rcb(R, a_pts(R)[0], t["12"])),
}


def assoc_tables():
    t = {}
    for k, (_, f) in ASSOC_LV.items():
        t[k] = f(Deg(), t)
    sizes = [rd_sizes(a_minor(Deg(), m, t["l"], t["r"])) for m in range(3)]
    assert [max(s[i] for s in sizes) for i in range(3)] == ASSOC_N, sizes
    return t


def assoc_check(gx, gy):
    n0, n1, n2 = ASSOC_N
    ok = tot = 0
    for i in range(n0):
        for j in range(n1):
            for l in range(n2):
                for sig in range(8):
                    R = Plain([gx[i], gx[j], gx[l]], sgn(sig, [gy[i], gy[j], gy[l]]))
                    a0, a1, a2 = a_pts(R)
                    lt, rt = rcb(R, rcb(R, a0, a1), a2), rcb(R, a0, rcb(R, a1, a2))
                    ok += all(a_minor(R, m, lt, rt) % P == 0 for m in range(3))
                    tot += 1
    assert ok == tot == n0 * n1 * n2 * 8
    print(f"assoc: {ok}/{tot} sign-points zero")


def gen_assoc_degrees():
    t, ns, o = assoc_tables(), f"seq![{ASSOC_N[0]}int, {ASSOC_N[1]}, {ASSOC_N[2]}]", []
    for k, (expr, _) in ASSOC_LV.items():
        st = f"{expr} == pdl_assoc_{k}()"
        o.append(f"""/// {expr}.
pub(crate) open spec fn pdl_assoc_{k}() -> PD {{
    {pd_lit(t[k])}
}}

pub(crate) proof fn lemma_assoc_deg_{k}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
    for m in range(3):
        st = f"deg_ok(minor_d({m}, pdl_assoc_l(), pdl_assoc_r()), {ns})"
        o.append(f"""pub(crate) proof fn lemma_assoc_deg_m{m}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
    return "".join(o)


def gen_grid_assoc(part):
    gx, gy = grid_points()
    if part == "a":
        assoc_check(gx, gy)
    rows, (_, n1, n2) = ASSOC_I[part], ASSOC_N
    o = [HEADER, f"""//! Chunked `compute_only` checks of assoc_id.rs's three minors at grid cells (i, j, l) with
//! {rows.start} <= i < {rows.stop}, j < {n1}, l < {n2}, under all 8 y-signs"""
         + (", and the literal degree tables of\n//! its four RCB calls." if part == "a" else ".") + f"""
#[allow(unused_imports)]
use super::assoc_id::*;
#[allow(unused_imports)]
use super::rcb::*;
#[allow(unused_imports)]
use super::red::*;
use vstd::prelude::*;

verus! {{

"""]
    if part == "a":
        o.append(gen_assoc_degrees())
    for i in rows:
        for j in range(n1):
            for h in range(n2 // ASSOC_H):
                st = f"cells_ok(c_assoc(), {i}, {j}, {h * ASSOC_H}, {(h + 1) * ASSOC_H})"
                o.append(f"""proof fn lemma_assoc_{i}_{j}_{h}()
    ensures
        {st},
{{
    reveal(assoc_cell);
    assert({st}) by (compute_only);
}}

""")
            calls = "".join(f"    lemma_assoc_{i}_{j}_{h}();\n    lemma_cells_forall(c_assoc(), {i}, {j}, "
                            f"{h * ASSOC_H}, {(h + 1) * ASSOC_H});\n" for h in range(n2 // ASSOC_H))
            o.append(f"""proof fn lemma_assoc_w_{i}_{j}()
    ensures
        forall|l: int| 0 <= l < {n2} ==> #[trigger] assoc_cell({i}, {j}, l),
{{
{calls}    assert forall|l: int| 0 <= l < {n2} implies #[trigger] assoc_cell({i}, {j}, l) by {{
        assert(c_assoc()({i}, {j}, l));
    }}
}}

""")
        pick = " else ".join(f"if j == {j} {{\n        }}" for j in range(n1))
        calls = "".join(f"    lemma_assoc_w_{i}_{j}();\n" for j in range(n1))
        o.append(f"""proof fn lemma_assoc_row_{i}()
    ensures
        forall|j: int, l: int| 0 <= j < {n1} && 0 <= l < {n2} ==> #[trigger] assoc_cell({i}, j, l),
{{
{calls}    assert forall|j: int, l: int| 0 <= j < {n1} && 0 <= l < {n2} implies #[trigger] assoc_cell({i}, j, l) by {{
        {pick}
    }}
}}

""")
    rng = f"{rows.start} <= i < {rows.stop} && 0 <= j < {n1} && 0 <= l < {n2}"
    pick = " else ".join(f"if i == {i} {{\n        }}" for i in rows)
    calls = "".join(f"    lemma_assoc_row_{i}();\n" for i in rows)
    o.append(f"""pub(crate) proof fn lemma_assoc_cells_{part}()
    ensures
        forall|i: int, j: int, l: int| {rng} ==> #[trigger] assoc_cell(i, j, l),
{{
{calls}    assert forall|i: int, j: int, l: int| {rng} implies #[trigger] assoc_cell(i, j, l) by {{
        {pick}
    }}
}}

}} // verus!
""")
    return "".join(o)



# ---------------------------------------------------------------------------------------------
# chain: nG = O by double-and-add over n's bits, with per-operation inverse witnesses
# ---------------------------------------------------------------------------------------------

CHAIN_CHUNK = 8


def g_lit():
    src = (ROOT / OUT / "field.rs").read_text()
    return tuple(int(re.search(rf"fn {c}_LIT\(\) -> int {{\s*(\d+)int", src).group(1)) for c in ("GX", "GY"))


def padd_w(a, b):
    """order.rs `padd_fast` with its witness: (result, w); w = 0 when no inverse is taken."""
    if a is None or b is None or (a[0] == b[0] and (a[1] + b[1]) % P == 0):
        return point_add(a, b), 0
    (x1, y1), (x2, y2) = a, b
    den = 2 * y1 if x1 == x2 else x2 - x1
    w = pow(den, P - 2, P)
    assert den * w % P == 1
    num = 3 * x1 * x1 - 3 if x1 == x2 else y2 - y1
    lam = num * w % P
    x3 = (lam * lam - x1 - x2) % P
    r = (x3, (lam * (x1 - x3) - y1) % P)
    assert r == point_add(a, b)
    return r, w


def chain_data():
    """Chunks (E_k, PT_k, BITS_k, WS_k) and the final (E_32, PT_32)."""
    G = g_lit()
    bits = [c == "1" for c in bin(N)[3:]]  # the top bit seeds E_0 = 1
    first = len(bits) % CHAIN_CHUNK or CHAIN_CHUNK
    cuts = [0] + list(range(first, len(bits) + 1, CHAIN_CHUNK))
    e, acc, out = 1, G, []
    for lo, hi in zip(cuts, cuts[1:]):
        e0, a0, ws = e, acc, []
        for b in bits[lo:hi]:
            acc, w = padd_w(acc, acc)
            ws.append(w)
            if b:
                acc, w = padd_w(G, acc)
            else:
                w = 0
            ws.append(w)
            e = 2 * e + b
        out.append((e0, a0, bits[lo:hi], ws))
    assert e == N and len(out) == 32 and len(out[0][2]) == 7
    print(f"chain ends at O: {acc is None}")
    assert acc is None
    return out, (e, acc)


def gen_chain():
    ch, (e_end, _) = chain_data()
    n = len(ch)
    pt = lambda a: "SpecPoint::Infinity" if a is None else f"SpecPoint::Affine({a[0]}int, {a[1]}int)"
    o = [HEADER, f"""//! The nG = O chain: checkpoints PT_k = E_k G with PT_0 = G and PT_{n} = O. Each chunk lemma
//! checks `chain(PT_k, BITS_k, WS_k) == Some(PT_(k+1))` by `compute_only`, `lemma_n_bits` checks
//! E_(k+1) == bext(E_k, BITS_k) and E_{n} == n, and `lemma_chain` (order.rs) joins them.
#![allow(non_snake_case)]
#[allow(unused_imports)]
use super::field::*;
#[allow(unused_imports)]
use super::order::*;
#[allow(unused_imports)]
use crate::p256::*;
use vstd::prelude::*;

verus! {{

"""]
    for k, (e, a, bits, ws) in enumerate(ch):
        a_s = "G_LIT()" if k == 0 else pt(a)
        bs = ", ".join("true" if b else "false" for b in bits)
        wss = ",\n        ".join(f"{w}int" for w in ws)
        o.append(f"""spec fn E_{k}() -> nat {{
    {e}nat
}}

spec fn PT_{k}() -> SpecPoint {{
    {a_s}
}}

spec fn BITS_{k}() -> Seq<bool> {{
    seq![{bs}]
}}

spec fn WS_{k}() -> Seq<int> {{
    seq![
        {wss},
    ]
}}

""")
    o.append(f"""spec fn E_{n}() -> nat {{
    N_LIT() as nat
}}

spec fn PT_{n}() -> SpecPoint {{
    SpecPoint::Infinity
}}

""")
    for k in range(n):
        st = f"chain(PT_{k}(), BITS_{k}(), WS_{k}()) == Some(PT_{k + 1}())"
        o.append(f"""proof fn lemma_chain_{k}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
    st = " && ".join(f"bext(E_{k}(), BITS_{k}()) == E_{k + 1}()" for k in range(n))
    o.append(f"""proof fn lemma_n_bits()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
    for k in range(n):
        o.append(f"""proof fn lemma_step_{k}()
    requires
        scalar_mult(E_{k}(), p256_g()) == PT_{k}(),
    ensures
        scalar_mult(E_{k + 1}(), p256_g()) == PT_{k + 1}(),
{{
    lemma_chain_{k}();
    lemma_n_bits();
    lemma_chain(E_{k}(), BITS_{k}(), WS_{k}());
}}

""")
    steps = "".join(f"    lemma_step_{k}();\n" for k in range(n))
    o.append(f"""/// nG = O.
pub(crate) proof fn lemma_chain_all()
    ensures
        scalar_mult(N_LIT() as nat, p256_g()) == SpecPoint::Infinity,
{{
    lemma_group_consts();
    // 1 G = G + O = G
    assert(scalar_mult(0, p256_g()) == SpecPoint::Infinity);
    assert(scalar_mult(1, p256_g()) == point_add(p256_g(), scalar_mult(0, p256_g())));
{steps}}}

}} // verus!
""")
    return "".join(o)


GENERATORS = {"pratt.rs": gen_pratt, "torsion_cert.rs": gen_torsion, "grid_small.rs": gen_grid_small}
GENERATORS.update({f"grid_assoc_{k}.rs": (lambda k=k: gen_grid_assoc(k)) for k in ASSOC_I})
GENERATORS["chain.rs"] = gen_chain


def main():
    check = sys.argv[1:] == ["--check"]
    assert sys.argv[1:] in ([], ["--check"]), "usage: gen_p256_group.py [--check]"
    with tempfile.TemporaryDirectory() as tmp:
        dest = Path(tmp) if check else ROOT / OUT
        for name, gen in GENERATORS.items():
            (dest / name).write_text(gen(), encoding="utf-8")
        if check:
            bad = [n for n in GENERATORS if not filecmp.cmp(dest / n, ROOT / OUT / n, shallow=False)]
            if bad:
                sys.exit(f"gen_p256_group.py --check: stale: {', '.join(bad)}")
            print(f"gen_p256_group.py --check: {len(GENERATORS)} file(s) up to date")


if __name__ == "__main__":
    main()
